const NOTE_CATEGORIES=["论文阅读","模型判断","部署记录","页面改版"];function formatDate(t){if(!t)return"";const e=new Date(t);return Number.isNaN(e.getTime())?"":e.toLocaleDateString("zh-CN",{year:"numeric",month:"2-digit",day:"2-digit"})}function renderInto(t,e){if(!e||0===e.length)return void(t.parentElement.style.display="none");let n="";for(const t of e){const e=formatDate(t.createdAt);n+=`\n      <a class="section-lab-panel" href="/notes/article/?id=${t.id}" style="text-decoration:none;color:inherit;">\n        <h2>${t.title}</h2>\n        ${e?`<p style="font-size:0.82rem;color:var(--section-muted);margin-top:8px;">${e}</p>`:""}\n      </a>`}t.innerHTML=n}async function load(){try{const t=await fetch("/api/notion/articles?public=true&module=笔记"),e=await t.json();if(!t.ok)return;const n=e.articles||[];for(const t of NOTE_CATEGORIES){const e=document.querySelector("#notion-"+CSS.escape(t));if(!e)continue;const o=e.querySelector(".notion-sub-grid");renderInto(o,n.filter(e=>e.category===t))}}catch{for(const t of NOTE_CATEGORIES){const e=document.querySelector("#notion-"+CSS.escape(t));e&&(e.style.display="none")}}}load();